#!/usr/bin/env node
// Writes lychee.pending.toml (gitignored): the offline link check's exclude list, generated from
// the URL contract's pending entries (see scripts/pending-links.mjs). CI passes it with --config.
import { writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { pendingPaths, pendingPatterns } from "./pending-links.mjs";

const out = fileURLToPath(new URL("../lychee.pending.toml", import.meta.url));
const patterns = pendingPatterns();
const toml = [
  "# GENERATED by scripts/gen-lychee-config.mjs from tests/url-contract/silo.urls.json. Do not edit.",
  "# Pending (not yet ported) pages only; every other internal link is checked.",
  "exclude = [",
  ...patterns.map((p) => `  '${p}',`),
  "]",
  "",
].join("\n");
writeFileSync(out, toml);
console.log(`lychee.pending.toml: ${patterns.length} pending page(s) excluded: ${pendingPaths().join(" ")}`);
